/**
 * TASK: Complete DualReportCard, which implements BOTH provided interfaces.
 * Printable and Auditable are provided -- do not edit them.
 *
 * Both interfaces declare a default method called header(). When one class
 * implements both, Java refuses to guess which default wins, so the class MUST
 * override header() itself. Your override has to combine the two, in order:
 *
 *   Printable.super.header() + " " + Auditable.super.header()
 *
 * For a card titled "Q3" with audit id "A-7" that is:
 *   "== Q3 == [audit A-7]"
 *
 * The other two default methods, render() and auditLine(), must NOT be
 * overridden. They call header() themselves, so once your override is in place
 * they pick it up automatically:
 *
 *   render()    -> "== Q3 == [audit A-7]\n(printable)"
 *   auditLine() -> "== Q3 == [audit A-7] ok"
 */
interface Printable {

    String title();

    default String header() {
        return "== " + title() + " ==";
    }

    default String render() {
        return header() + "\n(printable)";
    }
}

interface Auditable {

    String auditId();

    default String header() {
        return "[audit " + auditId() + "]";
    }

    default String auditLine() {
        return header() + " ok";
    }
}

public class DualReportCard implements Printable, Auditable {

    private final String name;
    private final String id;

    public DualReportCard(String name, String id) {
        this.name = name;
        this.id = id;
    }

    @Override
    public String title() {
        // TODO: the report name
        return "";
    }

    @Override
    public String auditId() {
        // TODO: the audit id
        return "";
    }

    @Override
    public String header() {
        // TODO: both inherited headers, separated by a single space
        return "";
    }
}

