public class DualReportCardTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Object safe(java.util.function.Supplier<Object> body) {
        try {
            return body.get();
        } catch (Throwable t) {
            return "<threw " + t.getClass().getSimpleName() + ">";
        }
    }

    public static void main(String[] args) {
        DualReportCard card = new DualReportCard("Q3", "A-7");

        check("title", "Q3", safe(card::title));
        check("auditId", "A-7", safe(card::auditId));
        check("header merges both defaults", "== Q3 == [audit A-7]", safe(card::header));
        check("the inherited render picks up the override",
                "== Q3 == [audit A-7]\n(printable)", safe(card::render));
        check("so does the inherited auditLine",
                "== Q3 == [audit A-7] ok", safe(card::auditLine));

        Printable asPrintable = card;
        check("through the Printable type", "== Q3 == [audit A-7]\n(printable)",
                safe(asPrintable::render));

        Auditable asAuditable = card;
        check("through the Auditable type", "== Q3 == [audit A-7] ok",
                safe(asAuditable::auditLine));

        DualReportCard other = new DualReportCard("Year End", "ZZ-1");
        check("a second card", "== Year End == [audit ZZ-1]", safe(other::header));
        check("a second card audit line", "== Year End == [audit ZZ-1] ok",
                safe(other::auditLine));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

